/// <summary>
/// One off job to disable indexes
/// </summary>
class METDisableIndexes
{
}

Method.Source:
    /// <summary>
    /// Runs the class with the specified arguments.
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>
    public static void main(Args _args)
    {
        void disableIndex(str _tableName, str _indexName)

        {
            str strSQL;
            Connection conn;
            SqlStatementExecutePermission permission;

            strSQL = strFmt('ALTER INDEX [%1] ON [DBO].[%2] DISABLE;', _indexName, _tableName);
            try
            {
                permission = new SqlStatementExecutePermission(strSQL);
                conn = new Connection();
                permission = new SqlStatementExecutePermission(strSQL);
                permission.assert();
                conn.createStatement().executeUpdate(strSQL);

                // the permissions needs to be reverted back to original condition.
                CodeAccessPermission::revertAssert();
            }
            catch
            {
                error(strFmt('Error executing "%1"', strSQL));
                CodeAccessPermission::revertAssert();
            }
        }

        disableIndex(tableStr(LedgerJournalEntityStaging), 'I_5355STAGINGREVERSEENTRIESIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869VENDTRANSIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869TAX1099FIELDSIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869BANKRESPWORKERID_RUIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869BANKCURRENCYTRANSFERLOG_RUIDX');
        disableIndex(tableStr(LedgerJournalTrans), 'I_20869POOLRECID');
